import{_ as r,o as t,c as a,ae as n}from"./chunks/framework.Cqu5Y2mC.js";const c=JSON.parse('{"title":"Protokoll Sitzung 05","description":"","frontmatter":{},"headers":[],"relativePath":"05-Gemeinsam/2026-04-17-Protokoll.md","filePath":"05-Gemeinsam/2026-04-17-Protokoll.md"}'),i={name:"05-Gemeinsam/2026-04-17-Protokoll.md"};function l(o,e,s,h,u,d){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="protokoll-sitzung-05" tabindex="-1">Protokoll Sitzung 05 <a class="header-anchor" href="#protokoll-sitzung-05" aria-label="Permalink to &quot;Protokoll Sitzung 05&quot;">​</a></h1><p><strong>Datum:</strong> <em><strong>2026-04-17</strong></em><br><strong>Sitzung:</strong> <em><strong>05</strong></em><br><strong>Protokollführer:</strong> <em><strong>Sofia Jäger; Daniel Saracoglu; Jan Leidolt</strong></em></p><p><strong>Teilnehmer:</strong><br><strong>Sybit:</strong> <em><strong>Stephan Strittmatter</strong></em><br><strong>Lehrer:</strong> <em><strong>Stefan Martin, Karl Laber</strong></em><br><strong>Schüler:</strong><br><em><strong>01-Betrieb: Huzaifa</strong></em><br><em><strong>02-Hardware: Eray, Lukas, Marlon</strong></em><br><em><strong>03-Software: Felix, Jannick, Theodor</strong></em><br><em><strong>04-Projektleitung: Daniel, Jan, Sofia</strong></em></p><hr><h2 id="aktueller-stand-ruckblick-seit-der-letzten-sitzung" tabindex="-1">Aktueller Stand/ Rückblick seit der letzten Sitzung: <a class="header-anchor" href="#aktueller-stand-ruckblick-seit-der-letzten-sitzung" aria-label="Permalink to &quot;Aktueller Stand/ Rückblick seit der letzten Sitzung:&quot;">​</a></h2><h3 id="_1-betrieb" tabindex="-1">1. Betrieb: <a class="header-anchor" href="#_1-betrieb" aria-label="Permalink to &quot;1. Betrieb:&quot;">​</a></h3><ul><li>Zwei Sensoren im Gateway registriert</li><li>Beschreibung geschrieben, wie man einen neuen Sensor registriert</li><li>Aktuell setzen sie sich mit NGINX auseinander</li></ul><h3 id="_2-hardware" tabindex="-1">2. Hardware: <a class="header-anchor" href="#_2-hardware" aria-label="Permalink to &quot;2. Hardware:&quot;">​</a></h3><ul><li>Marlon modelliert eine CAD-Schiene als Halterung für den Sensor.</li><li>Lukas erstellt eine Benutzeranleitung für den Sensor.</li><li>Eray berechnet den Bereich der im Mülleimer durch den Sensor eingesehen werden kann.</li></ul><h3 id="_3-software" tabindex="-1">3. Software: <a class="header-anchor" href="#_3-software" aria-label="Permalink to &quot;3. Software:&quot;">​</a></h3><ul><li>Sie lesen sich in die neue MQTT-Technologie ein</li></ul><h3 id="_4-projektleitung" tabindex="-1">4. Projektleitung: <a class="header-anchor" href="#_4-projektleitung" aria-label="Permalink to &quot;4. Projektleitung:&quot;">​</a></h3><ul><li>E-Mail zur neuen Terminvereinbarung gesendet</li><li>Terminvorschläge: 12. Juni oder 19. Juni</li><li>Protokoll 17.04.2026 verfasst</li></ul><hr><h2 id="besprochene-themen-inhalt" tabindex="-1">Besprochene Themen/ Inhalt: <a class="header-anchor" href="#besprochene-themen-inhalt" aria-label="Permalink to &quot;Besprochene Themen/ Inhalt:&quot;">​</a></h2><h3 id="_1-gruppenwechsel" tabindex="-1">1. Gruppenwechsel <a class="header-anchor" href="#_1-gruppenwechsel" aria-label="Permalink to &quot;1. Gruppenwechsel&quot;">​</a></h3><ul><li>Marlon hat die Gruppe von Software zu Hardware offiziell gewechselt.</li><li>Grund: Er ist mit der Software-Thematik nicht sehr gut zurecht gekommen. Er kann dem Hardware Team mit seiner guten Expertise im Bereich 3D-Druck sehr weiterhelfen.</li></ul><h3 id="_2-selbststandiges-arbeiten" tabindex="-1">2. Selbstständiges Arbeiten <a class="header-anchor" href="#_2-selbststandiges-arbeiten" aria-label="Permalink to &quot;2. Selbstständiges Arbeiten&quot;">​</a></h3><ul><li>Herr Strittmatter unterstützt Team Software</li><li>Herr Laber unterstützt Team Hardware</li><li>Herr Martin unterstützt Team Betrieb/Infrastruktur</li></ul><hr><h2 id="ziele-bis-zur-nachsten-sitzung" tabindex="-1">Ziele bis zur nächsten Sitzung: <a class="header-anchor" href="#ziele-bis-zur-nachsten-sitzung" aria-label="Permalink to &quot;Ziele bis zur nächsten Sitzung:&quot;">​</a></h2><h3 id="_1-betrieb-1" tabindex="-1">1. Betrieb: <a class="header-anchor" href="#_1-betrieb-1" aria-label="Permalink to &quot;1. Betrieb:&quot;">​</a></h3><ul><li>NGINX auf dem Server installieren</li></ul><h3 id="_2-hardware-1" tabindex="-1">2. Hardware: <a class="header-anchor" href="#_2-hardware-1" aria-label="Permalink to &quot;2. Hardware:&quot;">​</a></h3><ul><li>3D gedrucktes Modell fertig gedruckt haben</li><li>Benutzeranleitung fertig schreiben</li></ul><h3 id="_3-software-1" tabindex="-1">3. Software: <a class="header-anchor" href="#_3-software-1" aria-label="Permalink to &quot;3. Software:&quot;">​</a></h3><ul><li>Sie wollen den MQTT-Simulator umprogrammieren.</li></ul><h3 id="_4-projektleitung-1" tabindex="-1">4. Projektleitung: <a class="header-anchor" href="#_4-projektleitung-1" aria-label="Permalink to &quot;4. Projektleitung:&quot;">​</a></h3><ul><li>Protokoll fertig schreiben und hochladen</li><li>Entscheiden, welche der beiden Terminvorschläge wahrgenommen werden sollen</li></ul>',29)])])}const m=r(i,[["render",l]]);export{c as __pageData,m as default};
